238	    /**
239	     * The id of the existing owner this one is a soft duplicate of: an owner sharing this one's last
240	     * name and postcode but reachable on a different telephone, recorded at creation. {@code null}
241	     * when no such owner existed.
242	     */
243	    public Integer getPossibleDuplicateOf() {
244	        return this.possibleDuplicateOf;
245	    }
246	
247	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
248	        this.possibleDuplicateOf = possibleDuplicateOf;
249	    }
250	
251	    /**
252	     * Whether this owner has been soft-deleted: the record is retained but excluded from duplicate and
253	     * identity checks when creating new owners. A newly created owner is not deleted.
254	     */
255	    public boolean isDeleted() {
256	        return this.deleted;
257	    }
258	
259	    public void setDeleted(boolean deleted) {
260	        this.deleted = deleted;
261	    }
262	
263	    /**
264	     * Whether this owner was flagged as a possible duplicate of an existing one at creation, i.e.
265	     * whether {@link #getPossibleDuplicateOf()} identifies a matching owner.
266	     */
267	    @Transient
268	    public boolean getPossibleDuplicate() {
269	        return this.possibleDuplicateOf != null;
270	    }
271	
272	    /**
273	     * The owner's self link: the canonical REST path to this owner, {@code "/api/owners/<id>"}.
274	     * {@code null} until the owner has been assigned an id.
275	     */
276	    @Transient
277	    public String getSelfLink() {
278	        return (this.getId() != null) ? "/api/owners/" + this.getId() : null;
279	    }
280	
281	    /**
282	     * The owner's locality: the REGION portion of its {@code customerCode} (see
283	     * {@link CustomerCode}), which is the region derived from the postcode or city at creation. This
284	     * disambiguates cities that share a name. Yields {@code "UNKNOWN"} when the owner has no customer
285	     * code or it resolves to no region.
286	     */
287	    @Transient
288	    public String getLocality() {
289	        return CustomerCode.regionOf(this.customerCode);
290	    }
291	
292	    /**
293	     * The owner's IANA timezone, derived from its {@link #getLocality() locality} via the fixed
294	     * region-to-timezone table (see {@link RegionTimezone}). {@code null} when the locality has no
295	     * known timezone.
296	     */
297	    @Transient
298	    public String getTimezone() {
299	        return RegionTimezone.of(this.getLocality());
300	    }
301	
302	    /**
303	     * The owner's check digit: the single Luhn check digit computed over the digits of the
304	     * {@code customerCode}, guarding against transcription errors of the code.
305	     */
306	    @Transient
307	    public int getCheckDigit() {
308	        return Luhn.checkDigit(this.customerCode);
309	    }
310	
311	    /**
312	     * The owner's salutation: the {@link #getTitle() title} honorific followed by a space and the
313	     * last name (e.g. {@code "DR who"}), or just the last name when no title was supplied.
314	     */
315	    @Transient
316	    public String getSalutation() {
317	        return (this.title != null && !this.title.isBlank())
318	                ? this.title + " " + this.getLastName()
319	                : this.getLastName();
320	    }
321	
322	    /**
323	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
324	     * present, otherwise {@code "PHONE"}.
325	     */
326	    @Transient
327	    public String getContactPreference() {
328	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
329	    }
330	
331	    /**
332	     * The owner's telephone formatted for humans: the stored E.164 number rendered as its country
333	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). The
334	     * raw {@link #getTelephone() telephone} stays in compact E.164. See {@link E164}.
335	     */
336	    @Transient
337	    public String getTelephoneDisplay() {
338	        return E164.display(this.telephone);
339	    }
340	
341	    /**
342	     * The owner's age band: {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"} derived from the
343	     * birth date against the registration date (see {@link AgeBand}), or {@code null} when no birth
344	     * date was supplied.
345	     */
346	    @Transient
347	    public String getAgeBand() {
348	        return AgeBand.classify(this.birthDate, this.registrationDate);
349	    }
350	
351	    /**
352	     * The owner's fiscal year: the {@code FY<YY>} label of the fiscal year (starting 1 July)
353	     * containing its business-day-adjusted registration date (see {@link FiscalYear}), or
354	     * {@code null} when no registration date is set.
355	     */
356	    @Transient
357	    public String getFiscalYear() {
358	        return (this.registrationDate != null) ? FiscalYear.label(this.registrationDate) : null;
359	    }
360	
361	    /**
362	     * The owner's identity key: the single derived value all duplicate detection is expressed
363	     * through, formed as {@code <normalizedTelephone>|<email or empty>|<householdId or empty>}.
364	     * Two owners are duplicates only when their whole identity keys are equal, so members of one
365	     * household (same {@code householdId}) with different telephones have different keys.
366	     */
367	    @Transient
368	    public String getIdentityKey() {
369	        return blankToEmpty(this.telephone) + '|' + blankToEmpty(this.email) + '|' + blankToEmpty(this.householdId);
370	    }
371	
372	    private static String blankToEmpty(String value) {
373	        return (value == null) ? "" : value;
374	    }
375	
376	    protected Set<Pet> getPetsInternal() {
377	        if (this.pets == null) {
378	            this.pets = new HashSet<>();
379	        }
380	        return this.pets;
381	    }
382	
383	    protected void setPetsInternal(Set<Pet> pets) {
384	        this.pets = pets;
385	    }
386	
387	    public List<Pet> getPets() {
388	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
389	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
390	        return Collections.unmodifiableList(sortedPets);
391	    }
392	
393	    public void setPets(List<Pet> pets) {
394	        this.pets = new HashSet<>(pets);
395	    }
396	
397	    public void addPet(Pet pet) {
398	        getPetsInternal().add(pet);
399	        pet.setOwner(this);
400	    }
401	
402	    /**
403	     * Return the Pet with the given name, or null if none found for this Owner.
404	     *
405	     * @param name to test
406	     * @return true if pet name is already in use
407	     */
408	    public Pet getPet(String name) {
409	        return getPet(name, false);
410	    }
411	
412	    /**
413	     * Return the Pet with the given name, or null if none found for this Owner.
414	     *
415	     * @param name to test
416	     * @return true if pet name is already in use
417	     */
418	    public Pet getPet(String name, boolean ignoreNew) {
419	        name = name.toLowerCase();
420	        for (Pet pet : getPetsInternal()) {
421	            if (!ignoreNew || !pet.isNew()) {
422	                String compName = pet.getName();
423	                compName = compName.toLowerCase();
424	                if (compName.equals(name)) {
425	                    return pet;
426	                }
427	            }
428	        }
429	        return null;
430	    }
431	
432	    public Pet getPet(Integer petId) {
433	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
434	    }
435	
436	    @Override
437	    public String toString() {
438	        return new ToStringCreator(this)
439	
440	            .append("id", this.getId())
441	            .append("new", this.isNew())
442	            .append("lastName", this.getLastName())
443	            .append("firstName", this.getFirstName())
444	            .append("address", this.address)
445	            .append("city", this.city)
446	            .append("telephone", this.telephone)
447	            .toString();
448	    }
449	}
