1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Optional;
4	
5	import net.officefloor.server.http.ServerHttpConnection;
6	import org.springframework.samples.petclinic.rest.escalation.IdempotentReplayException;
7	
8	/**
9	 * First step of create-owner: when the request carries an {@code Idempotency-Key} that an earlier
10	 * create already used, short-circuits the pipeline by throwing {@link IdempotentReplayException}
11	 * with the original owner's id, so the duplicate is never validated, built or persisted. A new or
12	 * absent key simply lets the pipeline proceed to {@link ValidateRequiredOwnerFields}.
13	 */
14	public class CheckIdempotency {
15	
16	    public void service(ServerHttpConnection connection, IdempotencyStore idempotencyStore)
17	            throws IdempotentReplayException {
18	        Optional<Integer> existingOwnerId = IdempotencyStore.keyOf(connection).flatMap(idempotencyStore::find);
19	        if (existingOwnerId.isPresent()) {
20	            throw new IdempotentReplayException(existingOwnerId.get());
21	        }
22	    }
23	}
