1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Map;
6	import java.util.function.Function;
7	
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
11	import org.springframework.util.StringUtils;
12	import org.springframework.web.bind.annotation.RequestBody;
13	
14	/**
15	 * Rejects a create-owner request that is missing or blank in any required field, before
16	 * {@link BuildOwner} runs. Collects every offending field so the response reports them all
17	 * at once. Publishes the validated body for later steps, since the HTTP body is read once.
18	 * The address is checked in its composed, normalized form (see {@link AddressNormalizer#compose}), so
19	 * a request is accepted when it supplies an address in either form — a non-blank {@code addressLine1}
20	 * or the flat {@code address} — and rejected when neither yields a non-blank address.
21	 */
22	public class ValidateRequiredOwnerFields {
23	
24	    /** Required fields, paired with their accessor, in the order reported. */
25	    private static final List<Map.Entry<String, Function<OwnerFieldsDto, String>>> REQUIRED = List.of(
26	            Map.entry("firstName", OwnerFieldsDto::getFirstName),
27	            Map.entry("lastName", OwnerFieldsDto::getLastName),
28	            Map.entry("address", dto -> AddressNormalizer.compose(
29	                    dto.getAddressLine1(), dto.getAddressLine2(), dto.getAddress())),
30	            Map.entry("city", OwnerFieldsDto::getCity),
31	            Map.entry("telephone", OwnerFieldsDto::getTelephone));
32	
33	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
34	            throws MissingOwnerFieldsException {
35	        List<String> missing = new ArrayList<>();
36	        for (Map.Entry<String, Function<OwnerFieldsDto, String>> field : REQUIRED) {
37	            if (!StringUtils.hasText(field.getValue().apply(request))) {
38	                missing.add(field.getKey());
39	            }
40	        }
41	        if (!missing.isEmpty()) {
42	            throw new MissingOwnerFieldsException(missing);
43	        }
44	        validated.set(request);
45	    }
46	}
