1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.util.StringUtils;
6	
7	/**
8	 * Normalizes an owner request's address in place into canonical form (see {@link AddressNormalizer}):
9	 * trimmed, whitespace-collapsed, upper-cased, with common street-type abbreviations expanded.
10	 * Normalization applies to whichever fields are supplied — the structured {@code addressLine1} /
11	 * {@code addressLine2} when present, otherwise the flat {@code address} — and the flat {@code address}
12	 * is set to the composed canonical value, so every later step (storage, household identity) reads one
13	 * normalized address regardless of the form it arrived in.
14	 */
15	public class NormalizeOwnerAddress {
16	
17	    public void service(@Val OwnerFieldsDto request) {
18	        if (StringUtils.hasText(request.getAddressLine1())) {
19	            request.setAddressLine1(AddressNormalizer.normalize(request.getAddressLine1()));
20	            request.setAddressLine2(StringUtils.hasText(request.getAddressLine2())
21	                    ? AddressNormalizer.normalize(request.getAddressLine2()) : null);
22	        }
23	        request.setAddress(AddressNormalizer.compose(
24	                request.getAddressLine1(), request.getAddressLine2(), request.getAddress()));
25	    }
26	}
