1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes an owner request's telephone in place into E.164 form (see {@link E164Telephone}).
9	 * Runs after the field is known present and before the DTO is applied to an entity, so owner
10	 * telephones are stored, returned and duplicate-checked as their E.164 value. Rejects with 400
11	 * when no valid E.164 number can be formed.
12	 */
13	public class NormalizeOwnerTelephone {
14	
15	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
16	        String e164 = E164Telephone.format(request.getTelephone());
17	        if (e164 == null) {
18	            throw new InvalidTelephoneException(request.getTelephone());
19	        }
20	        request.setTelephone(e164);
21	    }
22	}
