1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
7	
8	/**
9	 * Rejects a create-owner request whose city already holds the maximum number of owners, before
10	 * {@link BuildOwner} runs. A city is full once it contains {@value #CAPACITY} or more owners, so the
11	 * next one would be the ({@value #CAPACITY}+1)th. Rejects with 409 otherwise.
12	 */
13	public class EnsureCityCapacity {
14	
15	    /** Maximum owners a single city may hold; the next create is rejected. */
16	    static final int CAPACITY = 50;
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws CityAtCapacityException {
20	        long count = ownerRepository.countByCity(request.getCity());
21	        if (count >= CAPACITY) {
22	            throw new CityAtCapacityException(request.getCity(), count);
23	        }
24	    }
25	}
