1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
8	
9	/**
10	 * Rejects a create-owner request whose supplied registration date is later than the server's
11	 * current date. A missing date is left for {@link ResolveRegistrationDate} to default. Runs before
12	 * the date is resolved so a future date is a 400, not silently rolled forward to a business day.
13	 */
14	public class ValidateRegistrationDate {
15	
16	    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
17	        LocalDate supplied = request.getRegistrationDate();
18	        if (supplied == null) {
19	            return;
20	        }
21	        LocalDate serverDate = LocalDate.now();
22	        if (supplied.isAfter(serverDate)) {
23	            throw new FutureRegistrationDateException(supplied, serverDate);
24	        }
25	    }
26	}
