2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	import org.springframework.util.StringUtils;
7	
8	/**
9	 * Shared address normalization for created owners: trims and collapses whitespace, upper-cases,
10	 * and expands common street-type abbreviations ({@code ST->STREET}, {@code RD->ROAD},
11	 * {@code AVE->AVENUE}). Used to store and return an owner's address in canonical form (see
12	 * {@link NormalizeOwnerAddress}), to reject an address that is blank once normalized
13	 * ({@link ValidateRequiredOwnerFields}) and to compare addresses for household identity
14	 * ({@link Household}).
15	 */
16	final class AddressNormalizer {
17	
18	    /** Street-type abbreviations expanded to their full word, keyed by their upper-cased token. */
19	    private static final Map<String, String> ABBREVIATIONS = Map.of(
20	            "ST", "STREET",
21	            "RD", "ROAD",
22	            "AVE", "AVENUE");
23	
24	    private AddressNormalizer() {
25	    }
26	
27	    /**
28	     * The normalized form of an address: leading/trailing and repeated inner whitespace collapsed to
29	     * a single space, upper-cased, and each known street-type abbreviation expanded. A {@code null}
30	     * or all-whitespace address normalizes to the empty string.
31	     */
32	    static String normalize(String address) {
33	        if (address == null) {
34	            return "";
35	        }
36	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
37	        if (collapsed.isEmpty()) {
38	            return "";
39	        }
40	        String[] tokens = collapsed.split(" ");
41	        StringBuilder normalized = new StringBuilder();
42	        for (int i = 0; i < tokens.length; i++) {
43	            if (i > 0) {
44	                normalized.append(' ');
45	            }
46	            normalized.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
47	        }
48	        return normalized.toString();
49	    }
50	
51	    /**
52	     * The single canonical address for an owner request, preferring the structured form over the flat
53	     * one. When {@code addressLine1} is supplied it is used (normalized), with the normalized
54	     * {@code addressLine2} appended after a single space when present; otherwise the flat
55	     * {@code address} is used (normalized). This is what every step that reads an owner's address —
56	     * validation, storage and household identity — sees, so structured and flat requests behave
57	     * identically downstream. Yields the empty string when no address is supplied in either form.
58	     */
59	    static String compose(String addressLine1, String addressLine2, String address) {
60	        if (!StringUtils.hasText(addressLine1)) {
61	            return normalize(address);
62	        }
63	        String line1 = normalize(addressLine1);
64	        return StringUtils.hasText(addressLine2) ? line1 + ' ' + normalize(addressLine2) : line1;
65	    }
66	}
