1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * Business-day rules for registration dates. A registration date must fall on a business
9	 * day: not a Saturday or Sunday, and not one of the fixed public holidays. A date landing on
10	 * a weekend or a public holiday rolls forward to the next non-holiday business day.
11	 */
12	public final class BusinessDay {
13	
14	    /** Fixed public holidays that the business-day roll skips. */
15	    private static final Set<LocalDate> HOLIDAYS = Set.of(
16	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
17	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
18	            LocalDate.parse("2026-12-28"));
19	
20	    private BusinessDay() {
21	    }
22	
23	    /**
24	     * Rolls {@code date} forward to the next business day when it falls on a weekend or a
25	     * public holiday; a date that already lands on a business day is returned unchanged.
26	     */
27	    public static LocalDate rollForward(LocalDate date) {
28	        while (!isBusinessDay(date)) {
29	            date = date.plusDays(1);
30	        }
31	        return date;
32	    }
33	
34	    private static boolean isBusinessDay(LocalDate date) {
35	        DayOfWeek day = date.getDayOfWeek();
36	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !HOLIDAYS.contains(date);
37	    }
38	}
